window.kbPageData["views/entry/k-d6b396bca4211d79"] = {"key":"entry/k-d6b396bca4211d79","state":{"route":"entry/k-d6b396bca4211d79"},"node":{"id":"k-d6b396bca4211d79","mode":"k","title":"等差数列求和公式","type":"原理与机制","domain":"数学","reading":"","intro":"","priority":100,"aliases":["等差数列前若干项的和等于项数乘以首末项的平均数","等差数列的和等于首项与末项的平均数乘以项数","等差数列前n项和","等差数列前n项和公式","等差数列求和","等差数列前n项和等于首末项平均值乘以项数","等差数列的和等于项数乘以首末项的平均值"],"qs":["国考 2024 副省级 行测#65","国考 2025 副省级 行测#76","国考 2025 行政执法 行测#72","江苏 2023 B类 行测#65","江苏 2025 B类 行测#59"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":4,"repeatPositions":1,"directorySummary":"等差数列前 n 项的和等于项数乘以首项与第 n 项的平均数，即 Sₙ = n(a₁ + aₙ)/2。","review":{"definition":"等差数列前 n 项的和等于项数乘以首项与第 n 项的平均数，即 Sₙ = n(a₁ + aₙ)/2。","explanation":"把前 n 项正序、倒序各列一遍，对应项相加都等于首项与末项之和。本题中，各行的数字个数依次为 1、3、5、……，第 29 行有 57 个数，故前 29 行共有 29×(1+57)/2 = 841 个数。第 30 行有 59 个数，中间是本行第 30 个，也就是从 2022 起倒数排列的第 871 个数，数值为 2022−870 = 1152，选 B。","references":[],"evidence":"每行的个数是首项为1、公差为2的等差数列","disposition":"独立词条","basis":"据原题和解析编释。","title":"等差数列求和公式","related":[],"examFocus":{"国考 2024 副省级 行测#65":"用等差数列的通项和求和公式，分别比较两条生产线第5天的当日产量和前5天的累计产量。","国考 2025 副省级 行测#76":"用等差数列求和计算折后累计销量，再按各自的销量和单位利润比较折前、折后的总利润。","江苏 2023 B类 行测#65":"用等差数列求和确定前面各行共占多少位置，再结合本行的居中位置和整数的降序排列定位。","江苏 2025 B类 行测#59":"用等差数列求和把总盆数与首排盆数、排数联系起来，再按盆数和排数的取值条件筛选摆法。"}},"readings":[{"origin":"k-d6b396bca4211d79","title":"等差数列求和公式","qs":["江苏 2023 B类 行测#65"],"definition":"等差数列前 n 项的和等于项数乘以首项与第 n 项的平均数，即 Sₙ = n(a₁ + aₙ)/2。","explanation":"把前 n 项正序、倒序各列一遍，对应项相加都等于首项与末项之和。本题中，各行的数字个数依次为 1、3、5、……，第 29 行有 57 个数，故前 29 行共有 29×(1+57)/2 = 841 个数。第 30 行有 59 个数，中间是本行第 30 个，也就是从 2022 起倒数排列的第 871 个数，数值为 2022−870 = 1152，选 B。","evidence":"每行的个数是首项为1、公差为2的等差数列","doubt":"","references":[]},{"origin":"k-ead87dd2376bb9ae","title":"等差数列求和公式","qs":["国考 2025 行政执法 行测#72"],"definition":"等差数列的前若干项之和等于这几项的首项与末项的平均数乘以项数。","explanation":"等差数列中，距首尾同样远的两项之和等于首末两项之和，因此这些项的平均数等于首末两项的平均数。本题从打折第一天起每天比前一天多卖10件，所以首日卖50件，第15天卖190件，15天共卖（50＋190）÷2×15＝1800件。打折前20天共卖800件。设定价为10、成本为x，由两段总利润相同可得1800（8－x）＝800（10－x），解得x＝6.4，成本是定价的64%，选B。","evidence":"开始打折第一天起，每天都比前一天多卖10件","doubt":"","references":[]},{"origin":"k-2a1b0713ed703395","title":"等差数列前n项和","qs":["国考 2024 副省级 行测#65"],"definition":"等差数列前n项和等于项数乘以首项与第n项的平均数，即Sₙ＝n(a₁＋aₙ)/2。首尾对称位置的两项之和恒等于a₁＋aₙ，所以前n项的平均数等于首尾两项的平均数。","explanation":"设第5天两条线的产量均为x件。往前推4天，甲、乙首日产量分别为x−4m和x＋8m。用前5项和公式计算累计产量，乙为甲的2倍，得到2x＋8m＝2(2x−4m)。解得x＝8m，乙首日产量16m是甲首日产量4m的4倍。","evidence":"第5天两条生产线的当日产量相同，且前5天乙的累计产量是甲的2倍","doubt":"","references":[]},{"origin":"k-7cc307c4deba174c","title":"等差数列求和","qs":["国考 2025 副省级 行测#76"],"definition":"等差数列前n项的和等于首项与第n项的平均值乘以n，即 Sₙ＝n(a₁＋aₙ)/2。","explanation":"等差数列中，与首、末项等距的两项之和恒等于首尾两项之和，所以全体项的平均值等于首尾平均值。本题折前最后一天售40件，折后第1天售50件，第15天售190件，因此折后15天共售15×(50＋190)÷2＝1800件。折前20天共售800件，设定价为p、单位成本为c，由1800(0.8p－c)＝800(p－c)得c＝0.64p。","evidence":"每天都比前一天多卖10件","doubt":"","references":[]},{"origin":"k-90f8d9f39082d494","title":"等差数列求和","qs":["江苏 2025 B类 行测#59"],"definition":"有限等差数列的和等于项数乘以首项与末项的平均值。","explanation":"将数列正序和倒序逐项相加，每对的和都是首项加末项。本题设首排有a盆，共n排，则末排有a+n−1盆，所以n(2a+n−1)=84。首排至少1盆，故n(n+1)≤84，且题意要求至少2排。检验范围内84的因数，只有n=3、4、7时a为正整数，共3种摆法。","evidence":"每一排的菊花盆数都比前一排多1盆","doubt":"","references":[]}]},"questions":{"国考 2024 副省级 行测#65":{"paper":"国考 2024 副省级 行测","n":65,"mod":"数量关系","src":["a566fec37e508ca7f975.pdf",12],"asrc":["a475ecf57d968bc14cd6.pdf",20],"card":"7cf39a569d2ed1aa942e8691","links":[{"id":"k-d6b396bca4211d79","role":"直接考查","why":"用首项与末项的平均数乘以项数，表示两条生产线各自前五天的累计产量。"}]},"国考 2025 副省级 行测#76":{"paper":"国考 2025 副省级 行测","n":76,"mod":"数量关系","src":["ffe12c35a46d4df574ec.pdf",13],"asrc":["ff0b352b44d417525086.pdf",23],"card":"3a2e592375b4aee64b626691","links":[{"id":"k-d6b396bca4211d79","role":"解题依据","why":"折后日销量每天增加相同件数，可用等差数列求累计销量。"}]},"国考 2025 行政执法 行测#72":{"paper":"国考 2025 行政执法 行测","n":72,"mod":"数量关系","src":["d8efe4e19862104d89c8.pdf",12],"asrc":["e2c4b1970d2b49eac0fd.pdf",23],"card":"253761c06c0588ad55c9c802","links":[{"id":"k-d6b396bca4211d79","role":"解题依据","why":"打折后的日销量按固定件数增长，可用等差数列求和得到累计销量。"}]},"江苏 2023 B类 行测#65":{"paper":"江苏 2023 B类 行测","n":65,"mod":"数量关系","src":["22262c34d18cd68fbee4.pdf",11],"asrc":["b08f2713d73015eac675.pdf",20],"card":"405c6249d5c6a099c4988949","links":[{"id":"k-d6b396bca4211d79","role":"解题依据","why":"对题设给定的各行项数求和，可得目标行之前共有多少个数。"}]},"江苏 2025 B类 行测#59":{"paper":"江苏 2025 B类 行测","n":59,"mod":"数量关系","src":["91e0d9fd02ca7ec6d61f.pdf",12],"asrc":["f2ff67a0f2a2f7e8e926.pdf",19],"card":"6b1a304bb61c0871454e2433","links":[{"id":"k-d6b396bca4211d79","role":"解题依据","why":"求和公式把总盆数、首排盆数和排数联系起来。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-d6b396bca4211d79":[["国考 2024 副省级 行测#65"],["国考 2025 副省级 行测#76","国考 2025 行政执法 行测#72"],["江苏 2023 B类 行测#65"],["江苏 2025 B类 行测#59"]]}};
